-- LemmaYard problem catalog for Supabase (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- Contains 20 problems, 11 tags and 275 test cases. Run it after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). It writes the same rows as
-- `pnpm problems:import`: upsert by slug (published), tags, and a full
-- replacement of each problem's tags and test cases, in one transaction.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (5, 6, 10, 14, 3, 19, 8, 13, 17, 15, 20, 11, 12, 9, 16, 7, 18, 1, 4, 2)
    AND "slug" NOT IN ($ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$edit-distance$ly$, $ly$fizz-buzz$ly$, $ly$house-robber$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$palindrome-number$ly$, $ly$product-of-array-except-self$ly$, $ly$reverse-string$ly$, $ly$trapping-rain-water$ly$, $ly$two-sum$ly$, $ly$valid-anagram$ly$, $ly$valid-parentheses$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$edit-distance$ly$, $ly$fizz-buzz$ly$, $ly$house-robber$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$palindrome-number$ly$, $ly$product-of-array-except-self$ly$, $ly$reverse-string$ly$, $ly$trapping-rain-water$ly$, $ly$two-sum$ly$, $ly$valid-anagram$ly$, $ly$valid-parentheses$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$array$ly$, $ly$Array$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$binary-search$ly$, $ly$Binary Search$ly$),
  ($ly$math$ly$, $ly$Math$ly$),
