INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$climbing-stairs$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$dynamic-programming$ly$, $ly$math$ly$);

